import{c as e,j as a,a as r,F as n,C as l,o,t as c}from"./chunks/framework.-a8jReyC.js";const m=["innerHTML"],b=JSON.parse('{"title":"FAQ - FlyCash","description":"","frontmatter":{"title":"FAQ - FlyCash"},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),f={name:"faq.md"},q=Object.assign(f,{setup(g){const d=[{title:"Perguntas Gerais",questions:[{title:"O que é o FlyCash?",description:["O FlyCash é uma ferramenta financeira que ajuda você a gerenciar seus gastos. Ele oferece recursos como recorrências personalizáveis, controle de orçamento por categorias e grupos, importação de faturas (PDF/OFX) e análise de fluxo de caixa."]},{title:"O FlyCash é gratuito?",description:["Sim! O FlyCash oferece um plano gratuito (Controle Inicial) com funcionalidades limitadas: até 10 categorias, 3 saldos, 100 transações por mês e 1 importação de fatura por mês. Para acesso ilimitado, há os planos Essencial e Equilíbrio Total."]},{title:"Como posso alterar ou cancelar meu plano?",description:["Você pode alterar ou cancelar seu plano diretamente na página do seu Perfil. Caso volte ao plano gratuito, você poderá selecionar quais categorias/grupos/saldos permanecerão ativos. Os demais ficarão disponíveis apenas para leitura."]}]},{title:"Importação de Faturas",questions:[{title:"Quais formatos de fatura posso importar?",description:["Você pode importar arquivos de fatura nos formatos <b>PDF</b> e <b>OFX</b>. Baixe o arquivo no app do seu banco e anexe no FlyCash."]},{title:"O que acontece com as transações importadas?",description:["As transações entram automaticamente com data, descrição e valor, com categorias sugeridas. O sistema também aponta possíveis duplicatas e reconhece parcelas para projetar nas próximas faturas."]},{title:"Como o FlyCash detecta duplicatas?",description:["Ao importar, o FlyCash compara descrição, valor, data e tipo com suas transações existentes. As prováveis duplicatas vêm desmarcadas para você revisar. Você também pode buscar manualmente uma possível duplicata e associá-la antes de importar."]},{title:"Qual o limite de importações por mês?",description:["No plano gratuito (Controle Inicial), o limite é de 1 importação de fatura por mês. Nos planos Essencial e Equilíbrio Total, a importação é ilimitada."]}]},{title:"Gerenciamento de Transações",questions:[{title:"Como registro um gasto do dia a dia?",description:['Selecione o mês de referência em uma categoria, clique em "Adicionar Transação", preencha data, valor e opcionalmente descrição, e salve. É rápido e pode ser feito direto do celular ou computador.']},{title:"O que acontece se eu marcar uma transação como recorrente?",description:["Ao configurar uma transação como recorrente, você pode definir um período e uma frequência (mensal, etc.). O FlyCash gera as transações futuras automaticamente.","Se precisar editar ou deletar uma recorrência, você terá opções para aplicar as mudanças a todas as transações ou apenas às próximas."]},{title:"Posso alterar apenas uma transação dentro de uma série recorrente?",description:["Sim, você pode alterar apenas uma transação individualmente, sem impactar as demais da série."]}]},{title:"Planos e Limitações",questions:[{title:"Quais são os limites do plano gratuito?",description:["No plano Controle Inicial, você pode criar até:","10 categorias","3 saldos","100 transações por mês","1 importação de fatura por mês"]},{title:"O que acontece se eu atingir o limite de transações do mês?",description:["Ao atingir o limite mensal de transações do plano gratuito (100), novas criações são bloqueadas até o reset do mês seguinte. O limite é por mês, não acumulativo."]},{title:"O que acontece com minhas informações ao cancelar o plano pago?",description:["Ao voltar para o plano gratuito, você poderá selecionar quais categorias, grupos e saldos manter ativos, respeitando os limites do plano gratuito. Os registros excedentes ficarão disponíveis apenas para leitura."]},{title:"Posso voltar ao plano pago e recuperar os registros excedentes?",description:["Sim, ao reativar o plano pago, todos os registros voltarão a ser editáveis e você poderá criar novos sem restrições."]}]},{title:"Fluxo de Caixa",questions:[{title:"O que é o gráfico mensal do Fluxo de Caixa?",description:["É um gráfico que mostra as entradas e saídas de cada mês do ano, com barras verdes (receitas) e vermelhas (despesas), para você acompanhar a evolução do seu fluxo financeiro."]},{title:"O que está incluso na análise por categoria?",description:["A análise por categoria mostra os totais e as principais transações por categoria. No plano Equilíbrio Total, há também comparativo e variação entre períodos, além de insights."]}]},{title:"Erros e Problemas",questions:[{title:"O que acontece se eu tenho um erro ou problema?",description:['Se você encontrar um erro ou problema, por favor, envie um email para <a href="mailto:support@flyca.sh">support@flyca.sh</a> com detalhes sobre o problema e o passo-a-passo para reproduzir o erro. Ou também pode abrir um ticket no <a href="https://discord.gg/VuQBBNhYXK">Discord</a>']},{title:"Não consigo visualizar minhas transações",description:['Se você não conseguir visualizar suas transações isso pode ser devido a uma versão antiga do FlyCash. Atualize para a versão mais recente clicando em "Recarregar" no popup que aparecer na sua tela ou pressionando <kbd>Ctrl</kbd> + <kbd>Shift</kbd> + <kbd>R</kbd> ou <kbd>Shift</kbd> + <kbd>F5</kbd>.']}]}];return(v,s)=>(o(),e("div",null,[s[0]||(s[0]=a("h1",{id:"faq-flycash",tabindex:"-1"},[r("FAQ - FlyCash "),a("a",{class:"header-anchor",href:"#faq-flycash","aria-label":'Permalink to "FAQ - FlyCash"'},"​")],-1)),s[1]||(s[1]=a("p",null,[r("Não encontrou sua pergunta? Acesse nosso "),a("a",{href:"https://discord.gg/VuQBBNhYXK",target:"_blank",rel:"noreferrer"},"discord"),r(" ou "),a("a",{href:"mailto:support@flyca.sh",target:"_blank",rel:"noreferrer"},"envie um email"),r(" e tire sua dúvida.")],-1)),(o(),e(n,null,l(d,t=>a("div",{key:t.title,class:"faq-category"},[a("h2",null,c(t.title),1),(o(!0),e(n,null,l(t.questions,i=>(o(),e("details",{class:"details custom-block",key:i.title},[a("summary",null,c(i.title),1),(o(!0),e(n,null,l(i.description,(p,u)=>(o(),e("p",{key:u,innerHTML:p},null,8,m))),128))]))),128))])),64))]))}});export{b as __pageData,q as default};
